-- PT111-S1-Q2. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT111-S1-Q2$batch10$ AND q.stimulus=$batch10$Lecturer: Given our current state of knowledge and technology, we can say that the generalization that the entropy of a closed system cannot decrease for any spontaneous process has not been falsified by any of our tests of that generalization. So we conclude it to be true universally. Yet, it must be admitted that this generalization has not been conclusively verified, in the sense that it has not been tested in every corner of the universe, under every feasible condition. Nevertheless, this generalization is correctly regarded as a scientific law; indeed, it is referred to as the Second Law of Thermodynamics.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, most justifies the lecturer's classification of the generalization described above?$batch10$ AND q.correct_choice=$batch10$D$batch10$) THEN RAISE EXCEPTION 'Question changed: PT111-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT111-S1-Q2$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S1-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT111-S1-Q2$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$The generalization is correctly regarded as a scientific law.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$No test available with current knowledge and technology has falsified it. It hasn't been conclusively verified everywhere and under every condition.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The lecturer admits the generalization isn't conclusively verified, so the principle can't demand that. What the generalization does have is confirmation as far as current science can go. The principle must say that this much is enough to count as a scientific law.$batch10$), (3, $batch10$Goal$batch10$, $batch10$If a generalization is confirmed to the extent current science allows, it is a scientific law.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT111-S1-Q2$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This says scientific laws haven't been falsified. That is "law, so not falsified." The lecturer needs the other direction, "not falsified, so law." This is the most-picked trap, so check which side of the rule the conclusion sits on.$batch10$), ($batch10$B$batch10$, $batch10$This tells us when something should not be a law. The generalization has been tested under far more than a few circumstances, so the principle doesn't apply, and it can't establish that something is a law anyway.$batch10$), ($batch10$C$batch10$, $batch10$This is about what will eventually be confirmed. It doesn't say anything about what counts as a scientific law.$batch10$), ($batch10$D$batch10$, $batch10$The generalization is confirmed as far as current science allows. Plug that into this principle and you get that it's considered a scientific law, which is the lecturer's classification.$batch10$), ($batch10$E$batch10$, $batch10$This starts from "regarded as a law" and predicts future verification. It doesn't tell us when to regard something as a law.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT111-S1-Q2$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
